.flashcard {
  perspective: 1000px;
  transform-style: preserve-3d;
  transition: transform 0.6s;
}
.flashcard.flipped {
  transform: rotateX(180deg);
}
.flashcard-front, .flashcard-back {
  backface-visibility: hidden;
  position: absolute;
  inset: 0;
}
.flashcard-back {
  transform: rotateX(180deg);
}

