flashcard_study_types.typescript:
// SRS Rating type
export type SRSRating = 'again' | 'hard' | 'good' | 'easy';

// SRS data for spaced repetition scheduling
export interface SRSData {
  interval: number;      // Days until next review
  easeFactor: number;    // Difficulty multiplier (default 2.5)
  repetitions: number;   // Number of successful reviews
  lastReview: number;    // Timestamp of last review
  nextReview: number;    // Timestamp of next review
}

// Study session state
export interface StudySession {
  id: string;
  cardIds: string[];
  currentIndex: number;
  startTime: number;
  endTime?: number;
  ratings: Map;
  completed: boolean;
}

// Study statistics
export interface StudyStats {
  cardsStudied: number;
  timeSpent: number;  // seconds
  correct: number;
  incorrect: number;
  streak: number;
  ratingDistribution: Record;
}

srs_algorithm.typescript:
const DEFAULT_EASE_FACTOR = 2.5;
const MIN_EASE_FACTOR = 1.3;

interface SM2Input {
  rating: SRSRating;        // again=1, hard=2, good=3, easy=4
  current: SRSData;         // Current SRS data for the card
}

interface SM2Output extends SRSData {
  // Updated SRS data for next review
}

function calculateNextReview(input: SM2Input): SM2Output {
  const { rating, current } = input;

  // Rating to quality mapping (SM-2 quality 0-5)
  const qualityMap: Record = {
    again: 0,
    hard: 2,
    good: 4,
    easy: 5,
  };

  const quality = qualityMap[rating);

  // Update ease factor
  let newEaseFactor = current.easeFactor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02));
  newEaseFactor = Math.max(MIN_EASE_FACTOR, newEaseFactor);

  // Calculate interval
  let newInterval: number;
  let newRepetitions: number;

  if (quality < 3) {
    // Failed - reset
    newRepetitions = 0;
    newInterval = 1;  // Review tomorrow
  } else {
    // Passed
    newRepetitions = current.repetitions + 1;

    if (newRepetitions === 1) {
      newInterval = 1;
    } else if (newRepetitions === 2) {
      newInterval = 6;
    } else {
      newInterval = Math.round(current.interval * newEaseFactor);
    }
  }

  return {
    interval: newInterval,
    easeFactor: newEaseFactor,
    repetitions: newRepetitions,
    lastReview: Date.now(),
    nextReview: Date.now() + newInterval * 24 * 60 * 60 * 1000,
  };
}

css_animations.css:
/* Flashcard flip animation */
.flashcard-container {
  perspective: 1000px;
  width: 100%;
  max-width: 600px;
  min-height: 300px;
}

.flashcard {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 300px;
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  cursor: pointer;
}

.flashcard.flipped {
  transform: rotateX(180deg);
}

.flashcard-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  background: var(--color-card);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-lg);
}

.flashcard-front {
  /* Front face styling */
}

.flashcard-back {
  transform: rotateX(180deg);
  /* Back face styling with rating buttons */
}

/* Rating buttons */
.rating-buttons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.5rem;
  margin-top: 1rem;
}

/* Progress indicator */
.progress-bar {
  width: 100%;
  height: 4px;
  background: var(--color-muted);
  border-radius: 2px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--color-primary);
  transition: width 0.3s ease;
}
